/**
 * Security Lab — client-safe threat-intelligence helpers.
 *
 * Everything produced here for a LAB scenario is explicitly labelled SIMULATED.
 * The platform cannot determine the real-world physical location of an actor;
 * only server-observed evidence (account, session, device fingerprint, request
 * IP, user agent) is factual, and it is presented separately.
 */
import type { LabScenario } from "./security-lab";

export const SIMULATED_LABEL = "SIMULATED LAB VALUE";

export const GEO_DISCLAIMER =
  "Simulated lab values are generated by the demonstration environment. SentinelCrypt does not and cannot establish the real physical location or real-world identity of an actor from a network request.";

export type LabThreatIntel = {
  threatSource: string;
  sourceIp: string;
  sourceIpSimulated: boolean;
  device: string;
  sessionLabel: string;
  threat: string;
  severity: string;
  riskScore: number;
  approximateRegion: string;
  regionSimulated: true;
};

const SEVERITY_BASE: Record<string, number> = {
  critical: 88,
  high: 72,
  medium: 52,
  low: 30,
  info: 12,
};

/** Application-defined risk heuristic (0-100) derived from severity + trust impact. */
export function riskScoreFrom(severity: string | null, trustDelta: number): number {
  const base = SEVERITY_BASE[(severity ?? "info").toLowerCase()] ?? 12;
  const impact = Math.min(20, Math.abs(trustDelta) / 2);
  return Math.max(0, Math.min(100, Math.round(base + impact)));
}

/** Short human reference for a transfer, e.g. TR-4F2A91C8. */
export function transferRef(id: string): string {
  return `TR-${id.replace(/-/g, "").slice(0, 8).toUpperCase()}`;
}

export function sessionRef(id: string | null): string {
  return id ? `LAB-SESSION-${id.replace(/-/g, "").slice(0, 5).toUpperCase()}` : "LAB-SESSION-NONE";
}

const SIMULATED_REGIONS: Record<LabScenario, string> = {
  INVALID_TOKEN: "Chennai, India",
  TOKEN_REPLAY: "Chennai, India",
  UNAUTHORIZED_RECEIVER: "Frankfurt, Germany",
  EXPIRED_TRANSFER: "Chennai, India",
  INTEGRITY_TAMPERING: "Singapore",
  SUSPICIOUS_SESSION: "Amsterdam, Netherlands",
  ABNORMAL_DOWNLOAD: "Chennai, India",
};

export function labIntel(input: {
  scenario: LabScenario;
  actorLabel: string;
  observedIp: string | null;
  sessionId: string | null;
  deviceFingerprint: string;
  threatType: string | null;
  severity: string | null;
  trustDelta: number;
  deviceTrusted?: boolean;
}): LabThreatIntel {
  return {
    threatSource: input.actorLabel,
    sourceIp: input.observedIp ?? "192.0.2.45",
    sourceIpSimulated: !input.observedIp || input.observedIp.startsWith("203.0.113."),
    device: input.deviceTrusted
      ? `Registered test device · ${input.deviceFingerprint}`
      : `Untrusted test device · ${input.deviceFingerprint}`,
    sessionLabel: sessionRef(input.sessionId),
    threat: input.threatType ?? "NO_THREAT_RULE_MATCHED",
    severity: (input.severity ?? "info").toUpperCase(),
    riskScore: riskScoreFrom(input.severity, input.trustDelta),
    approximateRegion: SIMULATED_REGIONS[input.scenario],
    regionSimulated: true,
  };
}

export type LabTimelineEntry = { at: string; label: string; detail?: string };

/** Chronological incident narrative built only from persisted evidence. */
export function buildIncidentTimeline(
  rows: { created_at: string; event: string; action?: string | null }[],
): LabTimelineEntry[] {
  return [...rows]
    .sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
    .map((r) => ({
      at: r.created_at,
      label: r.event.replace(/_/g, " "),
      ...(r.action ? { detail: r.action.replace(/_/g, " ").toLowerCase() } : {}),
    }));
}

export type SecurityPosture = "SECURE" | "ELEVATED RISK" | "ACTIVE INCIDENT";

export function securityPosture(input: {
  openIncidents: number;
  criticalOrHighLast24h: number;
  trustScore: number;
}): SecurityPosture {
  if (input.openIncidents > 0) return "ACTIVE INCIDENT";
  if (input.criticalOrHighLast24h > 0 || input.trustScore < 85) return "ELEVATED RISK";
  return "SECURE";
}
